/* ---------- Scan to Pay (3.0 Figma node 1837:49950 + Wallet 2.0 fee) ---------- */
const SP_MERCH_SUB = m => m.kind==='personal' ? 'Personal DuitNow QR' : 'DuitNow merchant · YouApp partner';
const KPL = {'2':'ABC','3':'DEF','4':'GHI','5':'JKL','6':'MNO','7':'PQRS','8':'TUV','9':'WXYZ'};
const keypad = (act='kp') => `<div class="kpad" aria-label="Keypad">${['1','2','3','4','5','6','7','8','9','','0','del'].map(k=>k===''?'<span></span>':`<button data-act="${k==='del'?act+'Del':act}" data-k="${k}" aria-label="${k==='del'?'Delete':k}">${k==='del'?ic('del'):`<b>${k}</b>${KPL[k]?`<small>${KPL[k]}</small>`:''}`}</button>`).join('')}</div>`;
const spLogo = `<div class="sp-dn"><em class="pml dn">D</em><small>DuitNow Pay</small></div>`;

V.scan = () => { const k = scen.kyc;
  const shop = `<div class="sp-illo">${ic('shop7')}</div><p class="sp-note">Scan any DuitNow QR code across Malaysia${P()>=4?' and get cashback at participating merchants':''}.</p>`;
  const head = `${statusBar()}<div class="topbar"><span class="sp-me">${img('avEmma','Elsa')}</span><span class="t-headline" style="flex:1; text-align:center">Pay Like a Local</span><button class="iconbtn" data-act="txHist" aria-label="History">${ic('receipt')}</button></div>`;
  if (k!=='passed') { const st = k==='rejected' ? ['xcircle','Verification rejected','Your ID photo was blurry. Please take it again in good light.','Re-submit','kycStart','err']
      : k==='review' ? ['hourglass','Verification in review','We\'ll notify you once you\'re verified. It usually takes a few minutes.','','','warn']
      : ['verify','Verify to start paying','Verify your identity once to pay any DuitNow QR. It takes about 2 minutes.','Verify Now','kycStart',''];
    return `<div class="screen">${head}<div class="scroll"><div class="pad16 stack" style="align-items:center; text-align:center; gap:10px; padding-top:8px">${spLogo}
      <span class="sp-kyc ${st[5]}">${ic(st[0])}</span><b class="t-headline">${st[1]}</b><p class="t-body muted" style="margin:0">${st[2]}</p>${st[3]?btn(st[3],st[4]):''}${shop}</div></div></div>`; }
  return `<div class="screen">${head}
  <div class="scroll" style="padding-bottom:16px"><div class="pad16 stack" style="gap:14px; align-items:center">${spLogo}
    <div class="sp-cam"><div class="vf"><i></i><i></i><i></i><i></i><span class="line"></span></div><small>Point at any DuitNow QR</small>
      <div class="sp-demo">${Object.values(MERCH).map(m=>`<button data-act="scanQr" data-id="${m.id}">${ic(m.kind==='personal'?'person':'qr')}${m.name}${m.fixed?' · fixed':''}</button>`).join('')}</div></div>
    <div class="sp-acts"><button class="sp-round" data-act="toast" data-msg="Flash on." aria-label="Flash">${ic('flash')}</button><button class="sp-myqr" data-act="myQr">My QR</button><button class="sp-round" data-act="sheet" data-s="gallery" aria-label="Pick from gallery">${ic('image')}</button></div>
    ${shop}</div></div></div>`; };

V.confirm = () => { const p = S.pay; const m = MERCH[p.id]; const t = T(); const amt = +p.amt || 0;
  const fee = feeFor(amt); const total = Math.round((amt + fee)*100)/100; const cbOn = P()>=4 && m.cbRate; const cb = cbOn ? amt*m.cbRate/100*t.cb/100 : 0;
  const overLim = amt > t.per; const low = total > bal(); const zero = amt<=0; const short = Math.max(0, total-bal());
  const btnTxt = low ? 'Top Up &amp; Pay '+RM(total) : 'Pay '+RM(total);
  return `<div class="screen">${statusBar()}${topBar('Scan and Pay')}
  <div class="scroll" style="padding-bottom:12px"><div class="pad16 stack" style="gap:12px; padding-top:4px">
    <div class="sp-payee">${img(m.img,m.name)}<span class="rf-col"><b>${m.name}</b><small>${SP_MERCH_SUB(m)}</small></span></div>
    <div class="sp-amt"><small>You Pay</small><div class="${overLim?'err':''}"><span>RM</span><b>${esc(p.amt||'0')}</b></div>
      ${m.fixed?'<small class="sp-fixed">Fixed amount set by the merchant</small>':''}
      ${overLim?`<small class="sp-err">Above your ${RMs(t.per)} per-payment limit on ${t.name}. ${NEXT[t.key]?'<button class="link" data-act="upgrade">Upgrade</button>':''}</small>`:''}</div>
    <div class="kvbox sp-box">
      <div class="kv"><span>Payment fee <small>${t.name}${t.name==='Free'?' tier':''}${floorApplies(amt)?' · RM1.50 minimum':''}${NEXT[t.key]?` · <button class="link" data-act="upgrade" style="font-size:12px">${TIERS[NEXT[t.key]].fee.toFixed(2)}% on ${TIERS[NEXT[t.key]].name}</button>`:''}</small></span><b><i class="sp-pct">${t.fee.toFixed(2)}%</i>${RM(fee)}</b></div>
      ${cbOn?`<div class="kv cb"><span>Cashback to you</span><b class="pos">+${RM(cb)}</b></div>`:''}
      <div class="kv"><span>Pay from</span><b>YouWallet · ${RM(bal())}</b></div>
      <div class="kv total"><span>Total</span><b>${RM(total)}</b></div></div>
    ${low&&!overLim&&!zero?`<div class="sp-short">${ic('alert')}<span><b>${RM(short)} short</b>Wallet ${RM(bal())}. Top up and pay in one step below.</span></div>`:''}
    ${m.kind==='personal'?`<div class="hint warn">${ic('warn')}<span>Paying a personal DuitNow account. This can't be reversed.</span></div>`:''}
  </div></div>
  <div class="w2foot sp-foot">${overLim||zero ? btn(btnTxt,'noop',{disabled:true}) : btn(btnTxt, low?'spTopUp':'spPay', {loading:S.busy, disabled:S.busy})}<p class="t-caption subtle" style="margin:0; text-align:center">The recipient receives ringgit instantly.</p></div>
  ${m.fixed?'':keypad()}</div>`; };

V.pin = () => { const n = (S.pinV||'').length;
  return `<div class="screen">${statusBar()}${topBar('Enter PIN')}
  <div class="scroll"><div class="pad16 stack" style="align-items:center; text-align:center; gap:10px; padding-top:20px">
    <b class="t-headline">Enter Your PIN</b><p class="t-body muted" style="margin:0">Payments of RM100 or more need your PIN.</p>
    <div class="pin-dots ${S.pinErr?'err':''}">${[0,1,2,3,4,5].map(i=>`<i class="${i<n?'on':''}"></i>`).join('')}</div>
    ${S.pinErr?'<small class="sp-err">Wrong PIN. 4 tries left.</small>':''}
    <button class="link" data-act="pinForgot">Forgot PIN?</button>
    <small class="subtle">Demo: any 6 digits works. 000000 shows the error.</small></div></div>
  ${keypad('pk')}</div>`; };

V.processing = () => `<div class="screen">${statusBar()}${topBar('Scan and Pay')}
  <div class="scroll"><div class="success" style="padding-top:24px"><div class="cele doc" aria-hidden="true"><span class="cele-ring"><span class="cele-art">${LEAF}</span></span></div>
    <b class="t-headline">Processing on Ethereum</b><span class="t-body muted">Waiting for your ${(S.tp&&S.tp.method||'usdt').toUpperCase()} top-up to confirm. We'll pay ${MERCH[S.pay.id].name} as soon as it arrives.</span>
    <div class="sp-prog"><i></i></div><small class="subtle">Confirmations 1 of 12 · about a minute</small></div></div>
  <div class="w2foot">${btn('Back to Wallet','home',{kind:'btn-tertiary'})}</div></div>`;

V.done = () => { const p = S.pay; const m = MERCH[p.id]; const t = T(); const amt = +p.amt; const fee = feeFor(amt); const cbOn = P()>=4 && m.cbRate; const cb = cbOn ? amt*m.cbRate/100*t.cb/100 : 0;
  return `<div class="screen">${statusBar()}${topBar('Scan and Pay')}
  <div class="scroll"><div class="success" style="padding-top:4px">${cele()}<small class="sp-paid">Paid</small><b class="sp-big">${RM(amt)}</b><span class="t-body subtle">to ${m.name} · DuitNow QR</span></div>
  <div class="pad16 stack" style="padding-top:10px"><div class="kvbox">
    <div class="kv"><span>Amount</span><b>${RM(amt)}</b></div>
    <div class="kv"><span>Payment fee <small>${t.fee.toFixed(2)}% · ${t.name}${t.name==='Free'?' tier':''}</small></span><b>${RM(fee)}</b></div>
    <div class="kv"><span>Total</span><b>${RM(amt+fee)}</b></div>
    ${cbOn?`<div class="kv cb"><span>Cashback to you</span><b class="pos">+${RM(cb)}</b></div>`:''}
    <div class="kv"><span>Updated balance</span><b>${RM(Math.max(0,bal()-amt-fee))}</b></div>
    <div class="kv"><span>Reference</span><b>YA-2610-0941</b></div>
    <div class="kv"><span>Date</span><b>23 Oct 2026, 6:25 pm</b></div></div></div></div>
  <div class="w2foot">${btn('Done','home')}${btn('Share This Moment','toast',{kind:'btn-secondary', data:'data-msg="Opens the share sheet."'})}</div></div>`; };

Object.assign(SHEETS, {
  gallery: () => `<div class="grab"></div><div class="stack" style="gap:10px"><div class="bz-row"><h2 class="t-title" style="margin:0">Recents</h2><button class="link" data-act="closeSheet">Cancel</button></div>
    <div class="sp-gal"><button data-act="galPick" aria-label="QR photo">${ic('qr')}</button>${['image','camera','image','image','image','image','image','image'].map((x,i)=>`<button data-act="galBad" aria-label="Photo ${i+2}" class="g${i%4}">${ic(x)}</button>`).join('')}</div>
    <small class="subtle">Demo: the first photo has a QR code. Others show the invalid image message.</small></div>`,
  badQr: () => `<div class="grab"></div><div class="stack" style="gap:10px; text-align:center; align-items:center"><span class="sp-kyc err">${ic('xcircle')}</span><b class="t-headline">Invalid QR image</b><p class="t-body muted" style="margin:0">This image doesn't contain a valid DuitNow QR code. Please try another image.</p>${btn('Close','closeSheet')}</div>`,
  topPay: () => { const p = S.pay; const amt = +p.amt||0; const total = spFees(amt).total; const short = Math.max(0,total-bal()); const exact = Math.max(20, Math.ceil(short*100)/100);
    const tp = S.tp; const opts = [[exact, `RM${exact.toFixed(2)} exact`], [100,'RM100'], [500,'RM500']];
    const row = x => { const on = tp.method===x.k; const dis = x.k==='wallet';
      return dis ? '' : `<button class="pmrow pm2 ${on?'on':''}" data-act="tpPick" data-m="${x.k}" aria-pressed="${on}">${pmIcon(x)}<span><b>${x.name}</b><small>${x.sub}</small></span><i></i></button>`; };
    const under = tp.amt < short;
    return `<div class="grab"></div><div class="stack" style="gap:10px"><h2 class="t-title" style="margin:0">Top Up and Pay</h2>
      <div class="sp-chips">${opts.map(([v,l])=>`<button class="${tp.amt===v?'on':''}" data-act="tpAmt" data-v="${v}">${l}</button>`).join('')}<button class="${tp.custom?'on':''}" data-act="tpCustom">Custom</button></div>
      ${tp.custom?`<div class="field ${under||tp.amt<20?'err':''}"><div class="prefin"><span>RM</span><input id="tpIn" inputmode="decimal" data-in="tpAmt" value="${tp.amt||''}"></div><span class="helper ${under||tp.amt<20?'':'neutral'}">${tp.amt<20?'Minimum top-up is RM20.':under?'Top up at least '+RM(short)+' to cover this payment.':'Minimum top-up RM20'}</span></div>`:'<small class="subtle">Minimum top-up RM20</small>'}
      ${['Card','Stablecoins'].map(g=>`<h3 class="sec" style="margin:4px 0 0; font-size:15px">${g==='Card'?'Debit or Credit Card':g}</h3><div class="pmlist">${PM.filter(x=>x.group===g).map(row).join('')}</div>`).join('')}
      ${btn('Top Up '+RM(tp.amt||0)+' &amp; Pay '+RM(total), under||tp.amt<20?'noop':'tpGo', {disabled:under||tp.amt<20})}</div>`; },
});
Object.assign(META, {
  scan:{name:'Scan to Pay', ph:1, fb:['F4'], rules:['From the 3.0 Figma Scan flow (node 1837:49950): DuitNow Pay logo, camera with “Point at any DuitNow QR”, Flash · My QR · Gallery, illustration.','Gallery: pick a photo with a QR; any other photo shows Invalid QR image.','Before KYC: Verify to start paying · In review · Verification rejected (Re-submit).','Any DuitNow QR works, merchant or personal (personal is pay-out only).']},
  confirm:{name:'Scan and Pay', ph:1, fb:['F4'], rules:['Figma layout: merchant, You Pay amount with the keypad (fixed-price QR: no keypad).','Gas Fee row replaced by the Wallet 2.0 Payment fee: tier % with RM1.50 minimum (Free/VIP) and a link to the next tier rate.','Button shows the total (amount + fee): Pay RMx.','Low balance: “RMx short” banner and Top Up & Pay, which opens the Top Up and Pay sheet (RMx exact / RM100 / RM500 / Custom, minimum top-up RM20, Debit or Credit Card or Stablecoins).','Above the per-payment limit: amount turns red, Upgrade link, button off.','RM100 or more asks for the PIN. Stablecoin top-ups show Processing on Ethereum first.']},
  pin:{name:'Enter PIN', ph:1, rules:['Payment threshold: RM100 or more needs the 6-digit PIN (Figma: Over payment threshold → PIN).','Wrong PIN shows the error and tries left.']},
  processing:{name:'Processing on Ethereum', ph:1, rules:['Shown when the top-up is a stablecoin sent from another wallet. Pays the merchant once it confirms.']},
  done:{name:'Paid', ph:1, rules:['Figma Paid screen with the leaf art. Receipt adds Wallet 2.0 rows: amount, payment fee (rate and tier), total, cashback (phase 4), updated balance, reference, date.','Done and Share this moment.']},
});
ORDER[0][1].splice(ORDER[0][1].indexOf('confirm')+1, 0, 'pin', 'processing');


/* ---------- Pay flow (3.1 Figma node 3:3371) ---------- */
const GAS = 1.00, MIN_PAY = 0; /* V2: no minimum payment */
const myrt = v => v.toLocaleString('en-MY',{minimumFractionDigits:2, maximumFractionDigits:2});
const tierBadge = t => `<span class="tbadge ${t.key}">${ic('crown')}${t.key==='free'?'FREE':t.name}</span>`;
/* V2: no gas fee on Scan and Pay (fee docs: no gas line). Elite 1-3 get the own fee rebate in Phase 2. */
const spFees = amt => { const fee = amt>0?feeFor(amt):0; const reb = rebFor(amt); return {fee, gas:0, reb, total: Math.round((amt+fee-reb)*100)/100}; };
const rebRow = reb => reb ? `<div class="kv"><span>${elName()} fee rebate</span><b class="pos"><i class="sp-pct g">${elLv().reb.toFixed(2)}%</i>-${reb.toFixed(2)}</b></div>` : '';
V.confirm = () => { const p = S.pay; const m = MERCH[p.id]; const t = T(); const amt = +p.amt || 0; const {fee, gas, reb, total} = spFees(amt);
  const overLim = amt > t.per; const low = total > bal(); const under = !m.fixed && amt>0 && amt < MIN_PAY; const zero = amt<=0; const short = Math.max(0, total-bal());
  const tu = [50,100,120,240].find(v=>v>=short) || Math.ceil(short);
  const off = overLim||zero||under;
  const label = low ? 'Top Up &amp; Pay RM'+tu : 'Pay Now';
  return `<div class="screen">${statusBar()}${topBar('Scan and Pay')}
  <div class="scroll" style="padding-bottom:12px"><div class="pad16 stack" style="gap:12px; padding-top:4px">
    <div class="sp-payee">${img(m.img,m.name)}<span class="rf-col"><b>${m.name}</b><small>${SP_MERCH_SUB(m)}</small></span></div>
    <div class="sp-amt"><small>You Pay</small><div><span>RM</span><b>${esc(p.amt||'0')}</b></div>
      ${overLim?`<small class="sp-err">This is above your ${RM(t.per,0)} per-payment limit on ${t.name}.</small>`:under?`<small class="sp-err">minimum payment is RM ${MIN_PAY}</small>`:''}
      ${m.fixed?'':`<div class="sp-chips c">${[50,100,120,240].map(v=>`<button class="${+p.amt===v?'on':''}" data-act="amtChip" data-v="${v}">${v}</button>`).join('')}</div>`}</div>
    <div class="kvbox sp-box">
      <div class="kv"><span class="sp-pf">Payment Fee ${tierBadge(t)}</span><b><i class="sp-pct g">${t.fee.toFixed(2)}%</i>${fee.toFixed(2)}</b></div>${rebRow(reb)}
      <div class="kv"><span>Pay from</span><b>YouWallet · MYRT ${myrt(bal())}</b></div></div>
    ${low&&!zero?`<div class="sp-short">${ic('alert')}<span><b>${RM(short)} short</b>Wallet MYRT ${myrt(bal())}. Top up and pay in one step below.</span></div>`:''}
    ${overLim&&NEXT[t.key]?`<button class="sp-unlock" data-act="upgrade"><span><b>Unlock More Rewards</b><small>Upgrade for more referral rewards and higher payment limits.</small></span>${ic('chev')}</button>`:''}
    ${m.kind==='personal'?`<div class="hint warn">${ic('warn')}<span>Paying a personal DuitNow account. This can't be reversed.</span></div>`:''}
  </div></div>
  <div class="w2foot sp-foot">${btn(label, off?'noop':low?'spTopUp':'spPay', {loading:S.busy, disabled:off||S.busy})}<p class="t-caption subtle" style="margin:0; text-align:center">The recipient receives ringgit instantly. You keep the memory and the cashback.</p></div>
  ${(!m.fixed && (low||overLim)) ? '' : keypad()}</div>`; };
V.done = () => { const p = S.pay; const m = MERCH[p.id]; const t = T(); const amt = +p.amt; const {fee, gas, reb, total} = spFees(amt); const cbOn = P()>=4 && m.cbRate; const cb = cbOn ? amt*m.cbRate/100*t.cb/100 : 0;
  const used = usedMon()+total;
  return `<div class="screen">${statusBar()}${topBar('Scan and Pay')}
  <div class="scroll"><div class="success" style="padding-top:4px">${cele()}<small class="sp-paid">Paid</small><b class="sp-big">RM ${amt.toLocaleString('en-MY',{maximumFractionDigits:2})}</b><span class="t-body subtle">to ${m.name} · DuitNow QR</span></div>
  <div class="pad16 stack" style="padding-top:10px; gap:10px"><div class="kvbox sp-box">
    <div class="kv"><span>Updated Balance</span><b>MYRT ${myrt(Math.max(0,bal()-total))}</b></div>
    <div class="kv"><span>Reference</span><b>YA-2610-0941</b></div>
    ${cbOn?`<div class="kv"><span>Cashback</span><b class="pos">+${RM(cb)}</b></div>`:''}
    <div class="kv"><span class="sp-pf">Payment Fee ${tierBadge(t)}</span><b><i class="sp-pct g">${t.fee.toFixed(2)}%</i>${fee.toFixed(2)}</b></div>${rebRow(reb)}
    <div class="kv"><span>Date</span><b>23 Oct 2026, 6:25 pm</b></div></div>
  </div></div>
  <div class="w2foot">${btn('Done','home')}${btn('Share this moment','shrPay',{kind:'btn-secondary'})}</div></div>`; };
Object.assign(META, {
  confirm:{name:'Scan and Pay', ph:1, fb:['F4'], rules:['From the 3.1 Figma pay flow (node 3:3371).','You Pay with amount chips 50 / 100 / 120 / 240 and the keypad. V2: no minimum payment amount (was RM20). Any amount above RM0 can be paid; the RM1.50 minimum fee still applies on Free/VIP.','V2: no Gas Fee row (fee docs have no gas line). Elite 1-3 in Phase 2 see an own fee rebate row (0.10 / 0.20 / 0.30%). Payment Fee with the tier badge (FREE / VIP / SVIP) and rate (2.00 / 1.85 / 1.70%, RM1.50 minimum for Free and VIP). Pay from YouWallet · MYRT.','Enough balance: Pay Now. Low balance: “RMx short” and Top Up & Pay RMx (smallest chip that covers it).','Above the per-payment limit: red message, Unlock More Rewards card (opens Choose your plan), button off.','Fixed-price QR: no chips or keypad.','RM100 or more asks for the PIN.'], open:['Figma fixed-price frames still show the keypad; the prototype hides it because the amount can’t change.']},
  done:{name:'Paid', ph:1, rules:['Updated Balance, Reference, Cashback (merchants with cashback), Payment Fee with tier badge and rate, own fee rebate (Elite 1–3, Phase 2), Date.','V2: no Gas Fee row and no Cashback Used bar.']},
});


