const MD_MONTHS = [{l:'All time', f:6.9, s:0, all:true},{l:'This month', f:1, s:0},
  ...[['Sep',.84],['Aug',.71],['Jul',.66],['Jun',.6],['May',.52],['Apr',.47],['Mar',.41],['Feb',.35],['Jan',.3]].map(([m,f],i)=>({l:m+' 2026', f, s:(i%2)+1}))];
const mdShift = (rows, s) => rows.map(([l,v],j)=>[l, Math.max(1, Math.min(95, v + [[0,0,0,0],[2,-3,2,-1],[-3,2,1,0]][s][j]))]);
const MD_P = {all:{l:'Overall', f:6.9, s:0, all:true}, day:{l:'Today', f:.04, s:1, sd:'+3% vs yesterday'}, week:{l:'This week', f:.22, s:2, sd:'+12% vs last week'},
  d7:{l:'Last 7 days', f:.25, s:1, sd:'-2% vs 7 days before'}, d30:{l:'Last 30 days', f:1, s:0, sd:'+8% vs 30 days before'}, m6:{l:'Last 6 months', f:4.2, s:2, sd:'+21% vs 6 months before'}, yr:{l:'This year', f:6.9, s:0, all:true}};
const mdData = (m, i) => { const x = typeof i==='string' ? MD_P[i] : MD_MONTHS[i]; const base = parseFloat(String(m.sales).replace(/[^0-9.]/g,''))||0; const cbBase = parseFloat(String(m.cb).replace(/[^0-9.]/g,''))||0;
  return {sales: Math.round(base*x.f), cb: Math.round(cbBase*x.f*100)/100, cbn: Math.round(m.cbn*x.f), cu: Math.round(m.cu*x.f), nw: Math.round(m.nw*x.f),
    ret: Math.max(0, Math.min(99, m.ret + [0,-3,2][x.s])), sd: x.all ? '' : x.sd || (x.s===0 ? m.sd : ['+5%','-2%'][x.s-1]), fem: Math.max(5, Math.min(95, m.fem + [0,-2,3][x.s])), age: mdShift(m.age, x.s), ctry: mdShift(m.ctry, x.s)}; };
